import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"从后端到智能合约","text":"理解 EVM · 写 Solidity · 做安全测试","tagline":"少一点术语堆砌，多一点可以运行、可以失败、可以验证的代码。面向有 Python / Web / 数据库经验的开发者。","image":{"src":"/logo.svg","alt":"Smart Contract Lab"},"actions":[{"theme":"brand","text":"从第 0 课开始 →","link":"/00-start/"},{"theme":"alt","text":"查看 12 周路线","link":"/roadmap"},{"theme":"alt","text":"查看实战工程","link":"https://github.com/yvanu/smart_contract_learn_book/tree/main/examples"}]},"features":[{"icon":"🧭","title":"工程师友好的知识迁移","details":"用 Python 后端的状态、事务、权限、接口概念，对照 EVM、Gas、ABI、事件与存储。"},{"icon":"🧪","title":"每一章都有可验证输出","details":"理论 → 最小源码 → 本地实验 → 失败用例 → 验收。不用真钱、不需要主网账户。"},{"icon":"🔒","title":"安全从第一天开始","details":"不是写出能运行的合约就算完成。重入、权限、回滚、签名和测试覆盖属于主课程。"},{"icon":"🧱","title":"一个完整项目贯穿学习","details":"用可取消、可退款、有阶段状态的托管 Escrow 项目练习设计、测试、部署与复盘。"},{"icon":"📘","title":"本地可重复实验","details":"首先用 Remix 与 Foundry 在本地学习，再进入测试网；不给刚入门的学习者引入真实资产风险。"},{"icon":"📊","title":"完成度真实透明","details":"文档是否写完、代码是否编译、测试是否通过、网络部署是否验证，分别记录。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1791601077000}'),i={name:"index.md"};function s(n,t,l,d,c,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="你会得到什么" tabindex="-1">你会得到什么？ <a class="header-anchor" href="#你会得到什么" aria-label="Permalink to &quot;你会得到什么？&quot;">​</a></h2><p><strong>第一阶段：</strong> 用 Remix/Foundry 部署并调用自己的第一个合约，能解释为什么一次状态写入要花 Gas。</p><p><strong>第二阶段：</strong> 用 Forge 写单测、失败预期、Fuzz 和基本属性约束，能够自己检查权限绕过与状态机。</p><p><strong>第三阶段：</strong> 做出一个具备托管、释放、退款、超时边界和事件审计的 Escrow 合约，写出验收报告。</p><div class="important custom-block github-alert"><p class="custom-block-title">学习安全边界</p><p>所有示例仅面向<strong>本地虚拟链或测试网</strong>。未经专业审计和额外安全测试，不得用于管理真实资金。不要将助记词、私钥或真实 Token 提交到仓库。</p></div><h2 id="完全没接触过区块链-这样开始" tabindex="-1">完全没接触过区块链？这样开始 <a class="header-anchor" href="#完全没接触过区块链-这样开始" aria-label="Permalink to &quot;完全没接触过区块链？这样开始&quot;">​</a></h2><p><strong>不建议第一天就背 EVM、ABI、Gas 的定义。</strong> 请依次完成下面的小目标：</p><ol><li><a href="/00-start/">00-1 从一个二手交易的故事认识智能合约</a>：先把钱包、账户、链和交易搞清楚。</li><li><a href="/00-start/environment">00-2 手把手在 Remix 部署 Counter</a>：不用真钱，不需要装 MetaMask，看到 0 → 1 → 2。</li><li><a href="/00-start/backend-map">00-3 Flask / 数据库和合约的区别</a>：把已有后端知识迁移过来。</li><li><a href="/01-solidity/">01-1 逐行读第一个 Solidity 权限合约</a>：分别用管理员和普通账户验证成功、失败。</li></ol><p>遇到陌生单词，请随时打开 <a href="/00-start/glossary">零基础术语词典</a>；遇到编译或部署错误，请查 <a href="/00-start/troubleshooting">新手排错手册</a>。每节按 <strong>故事 → 术语 → 代码 → 实操 → 结果 → 常见错误 → 自测</strong> 的顺序阅读。前四课做完再接触复杂测试与安全术语。</p><p>按 <a href="/roadmap">12 周路线</a> 每周推进，或直接进入 <a href="/00-start/">第一课</a>。</p>',10)])])}const _=a(i,[["render",s]]);export{h as __pageData,_ as default};
